{
  "name": "Chatterbox振荡器模拟后端",
  "name_en": "Chatterbox Shaker Backend",
  "manufacturer": "",
  "description": "用于振荡器流程的非实体软件组件。它提供振荡、停止振荡以及夹板锁定/解锁等接口，主要用于测试、调试或在未连接具体硬件时模拟振荡器行为。",
  "description_en": "A non-physical software component for shaker workflows. It provides interfaces for shaking, stopping, and plate locking/unlocking, mainly for testing, debugging, or simulating shaker behavior when no specific hardware is attached.",
  "actions": [
    {
      "action_name": "auto-shake",
      "description": "以指定速度启动振荡模拟。",
      "description_en": "Start simulated shaking at a specified speed."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡模拟。",
      "description_en": "Stop simulated shaking."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "检查是否支持夹板锁定功能。",
      "description_en": "Check whether plate locking is supported."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "执行夹板锁定模拟。",
      "description_en": "Simulate locking the plate."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "执行夹板解锁模拟。",
      "description_en": "Simulate unlocking the plate."
    }
  ],
  "tag_hints": [
    "shaker simulation",
    "non-physical backend",
    "lab automation testing",
    "plate locking",
    "workflow debugging"
  ]
}

